-- The Scrdsx logo (192x192 PNG, embedded). Logo.Get() writes it to the workspace once and returns an asset id for ImageLabels (nil when the executor cannot).
local Logo = {}
local DATA = ""
local path = "ScrdsxScript/logo_v2.png"
local cached

local function decode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
	local out, buf, bits = {}, 0, 0
	for i = 1, #s do
		local v = map[s:sub(i, i)]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local byte = math.floor(buf / 2 ^ bits)
				out[#out + 1] = string.char(byte)
				buf = buf - byte * 2 ^ bits
			end
		end
	end
	return table.concat(out)
end

function Logo.Get()
	if cached ~= nil then return cached or nil end
	cached = false
	pcall(function()
		if not (writefile and getcustomasset) then return end
		pcall(function() if makefolder then makefolder("ScrdsxScript") end end)
		if not (isfile and isfile(path)) then writefile(path, decode(DATA)) end
		cached = getcustomasset(path)
	end)
	return cached or nil
end

-- puts the logo (or a blue "S" badge when images are not available) into parent
function Logo.Make(parent, size, pos)
	local id = Logo.Get()
	local el
	if id then
		el = Instance.new("ImageLabel")
		el.BackgroundTransparency = 1
		el.Image = id
		el.ScaleType = Enum.ScaleType.Fit
	else
		el = Instance.new("Frame")
		el.BackgroundColor3 = Color3.fromRGB(64, 132, 255)
		el.BorderSizePixel = 0
		local cr = Instance.new("UICorner"); cr.CornerRadius = UDim.new(0.26, 0); cr.Parent = el
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1; t.Size = UDim2.fromScale(1, 1); t.Text = "S"; t.TextColor3 = Color3.new(1, 1, 1)
		t.Font = Enum.Font.GothamBold; t.TextSize = math.floor(size * 0.6); t.Parent = el
	end
	el.Size = UDim2.fromOffset(size, size)
	if pos then el.Position = pos end
	el.Parent = parent
	return el
end

return Logo
